import { renderHook } from '@testing-library/react-hooks';

import { useShouldMoveOut } from './useShouldMoveOut';

describe('useShouldMoveOut', () => {
    const onBack = jest.fn();
    const props = { elementID: 'active', elementIDs: ['active'], loadingElements: false, onBack };

    beforeEach(() => onBack.mockClear());

    it('keeps the view open while elements load, then exits if the active ID is absent', () => {
        const { rerender } = renderHook((options) => useShouldMoveOut(options), {
            initialProps: { ...props, elementIDs: ['other'], loadingElements: true },
        });

        expect(onBack).not.toHaveBeenCalled();
        rerender({ ...props, elementIDs: ['other'], loadingElements: false });
        expect(onBack).toHaveBeenCalledTimes(1);
    });

    it('keeps the view open when the active ID is present', () => {
        renderHook(() => useShouldMoveOut(props));
        expect(onBack).not.toHaveBeenCalled();
    });

    it.each<{ name: string; elementID?: string; elementIDs: string[] }>([
        { name: 'undefined ID', elementID: undefined, elementIDs: ['active'] },
        { name: 'empty ID', elementID: '', elementIDs: ['active'] },
        { name: 'empty list', elementID: 'active', elementIDs: [] },
    ])('exits for an $name', ({ elementID, elementIDs }) => {
        renderHook(() => useShouldMoveOut({ ...props, elementID, elementIDs }));
        expect(onBack).toHaveBeenCalledTimes(1);
    });
});
